package com.tanleathertracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class TanLeatherDimOverlay extends Overlay
{
	private static final Color DIM_COLOR = new Color(0, 0, 0, 180);
	private static final Color CAST_DIM_COLOR = new Color(0, 0, 0, 120);
	private static final Color TEXT_COLOR = Color.WHITE;
	private static final Color INEFFICIENT_COLOR = new Color(255, 200, 0);
	private static final String OUT_OF_HIDES_MESSAGE = "Out of hides!";
	private static final String INEFFICIENT_SUBLINE = "Inefficient cast — same runes, fewer hides";

	private final Client client;
	private final TanLeatherTrackerPlugin plugin;

	@Inject
	public TanLeatherDimOverlay(Client client, TanLeatherTrackerPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.shouldShowCastTimer())
		{
			return renderCastTimer(graphics);
		}

		if (plugin.shouldShowDim())
		{
			return renderOutOfHides(graphics);
		}

		return null;
	}

	private Dimension renderCastTimer(Graphics2D graphics)
	{
		Dimension size = client.getRealDimensions();

		if (plugin.shouldShowCastDim())
		{
			graphics.setColor(CAST_DIM_COLOR);
			graphics.fillRect(0, 0, size.width, size.height);
		}

		double seconds = plugin.getCastRemainingMs() / 1000.0;
		String text = String.format("%.1f", seconds);

		graphics.setColor(TEXT_COLOR);
		graphics.setFont(new Font("Arial", Font.BOLD, 48));
		FontMetrics fm = graphics.getFontMetrics();
		int x = (size.width - fm.stringWidth(text)) / 2;
		int y = (size.height / 2) + fm.getAscent() / 2;
		graphics.drawString(text, x, y);

		if (plugin.isLastCastInefficient())
		{
			graphics.setColor(INEFFICIENT_COLOR);
			graphics.setFont(new Font("Arial", Font.BOLD, 16));
			FontMetrics subFm = graphics.getFontMetrics();
			int subX = (size.width - subFm.stringWidth(INEFFICIENT_SUBLINE)) / 2;
			int subY = y + subFm.getHeight() + 4;
			graphics.drawString(INEFFICIENT_SUBLINE, subX, subY);
		}

		return size;
	}

	private Dimension renderOutOfHides(Graphics2D graphics)
	{
		Dimension size = client.getRealDimensions();

		graphics.setColor(DIM_COLOR);
		graphics.fillRect(0, 0, size.width, size.height);

		graphics.setColor(TEXT_COLOR);
		graphics.setFont(new Font("Arial", Font.BOLD, 24));
		FontMetrics fm = graphics.getFontMetrics();
		int x = (size.width - fm.stringWidth(OUT_OF_HIDES_MESSAGE)) / 2;
		int y = (size.height / 2) + fm.getAscent() / 2;
		graphics.drawString(OUT_OF_HIDES_MESSAGE, x, y);

		return size;
	}
}

package com.tanleathertracker;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

public class TanLeatherTrackerOverlay extends OverlayPanel
{
	private static final Color INEFFICIENT_COLOR = new Color(255, 200, 0);
	private static final Color OUT_OF_RUNES_COLOR = new Color(255, 80, 80);

	private final TanLeatherTrackerPlugin plugin;
	private final TanLeatherTrackerConfig config;

	@Inject
	public TanLeatherTrackerOverlay(TanLeatherTrackerPlugin plugin, TanLeatherTrackerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		boolean outOfRunes = plugin.isOutOfRunes();
		if (!config.showOverlay() || (!plugin.shouldShowCounter() && !outOfRunes))
		{
			return null;
		}

		if (plugin.shouldShowCounter())
		{
			int castCount = plugin.getCastCount();
			int maxCasts = plugin.getMaxCasts();
			String displayText = castCount + " / " + maxCasts;

			Color textColor = (castCount >= maxCasts && maxCasts > 0) ? Color.RED : Color.WHITE;

			panelComponent.getChildren().add(LineComponent.builder()
				.left("Tan Casts:")
				.right(displayText)
				.rightColor(textColor)
				.build());
		}

		if (config.showInefficientWarning() && plugin.isInefficient())
		{
			String rightText;
			if (plugin.shouldSuggestDeposit())
			{
				rightText = "deposit " + plugin.hidesToDeposit();
			}
			else
			{
				rightText = "need " + plugin.hidesShortOfFullCast() + " more";
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Inefficient")
				.right(rightText)
				.leftColor(INEFFICIENT_COLOR)
				.rightColor(INEFFICIENT_COLOR)
				.build());
		}

		if (outOfRunes)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Out of runes!")
				.leftColor(OUT_OF_RUNES_COLOR)
				.build());
		}

		return super.render(graphics);
	}
}

package com.tanleathertracker;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.BasicStroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class TanLeatherSpellHighlightOverlay extends Overlay
{
	// Varbits.SPELLBOOK value for the Lunar spellbook
	private static final int LUNAR_SPELLBOOK_VARBIT_VALUE = 2;

	private static final Stroke OUTLINE_STROKE = new BasicStroke(2f);

	// How many top-level children of the spellbook interface to scan
	private static final int MAX_TOP_LEVEL_CHILDREN = 64;

	private final Client client;
	private final TanLeatherTrackerPlugin plugin;
	private final TanLeatherTrackerConfig config;

	@Inject
	public TanLeatherSpellHighlightOverlay(Client client, TanLeatherTrackerPlugin plugin, TanLeatherTrackerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showSpellHighlight()
			|| !plugin.hasEnoughHidesForCast()
			|| client.getVarbitValue(VarbitID.SPELLBOOK) != LUNAR_SPELLBOOK_VARBIT_VALUE)
		{
			return null;
		}

		Widget spell = findTanLeatherWidget();
		if (spell == null || spell.isHidden())
		{
			return null;
		}

		Rectangle bounds = spell.getBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			return null;
		}

		graphics.setColor(config.spellHighlightColor());
		graphics.setStroke(OUTLINE_STROKE);
		graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);

		return null;
	}

	private Widget findTanLeatherWidget()
	{
		for (int childId = 0; childId < MAX_TOP_LEVEL_CHILDREN; childId++)
		{
			Widget container = client.getWidget(InterfaceID.MAGIC_SPELLBOOK, childId);
			if (container == null)
			{
				continue;
			}
			Widget hit = searchForTanLeather(container);
			if (hit != null)
			{
				return hit;
			}
		}
		return null;
	}

	private Widget searchForTanLeather(Widget root)
	{
		if (root == null)
		{
			return null;
		}

		String name = root.getName();
		if (name != null && name.toLowerCase().contains("tan leather"))
		{
			return root;
		}

		Widget hit = searchArray(root.getDynamicChildren());
		if (hit != null) return hit;

		hit = searchArray(root.getStaticChildren());
		if (hit != null) return hit;

		hit = searchArray(root.getNestedChildren());
		return hit;
	}

	private Widget searchArray(Widget[] children)
	{
		if (children == null)
		{
			return null;
		}
		for (Widget child : children)
		{
			Widget hit = searchForTanLeather(child);
			if (hit != null)
			{
				return hit;
			}
		}
		return null;
	}
}

package com.tanleathertracker;

import java.awt.Color;
import java.awt.TrayIcon;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;

@ConfigGroup("tanleathertracker")
public interface TanLeatherTrackerConfig extends Config
{
	@ConfigSection(
		name = "Overlay",
		description = "Top-left cast counter overlay options",
		position = 0
	)
	String overlaySection = "overlay";

	@ConfigSection(
		name = "Cast timer",
		description = "Post-cast countdown overlay",
		position = 1
	)
	String castTimerSection = "castTimer";

	@ConfigSection(
		name = "Spellbook highlight",
		description = "Outline the Tan Leather icon on the Lunar spellbook",
		position = 2
	)
	String highlightSection = "highlight";

	@ConfigSection(
		name = "Out of hides screen dim",
		description = "Dim the screen when hides drop below 5",
		position = 3
	)
	String dimSection = "dim";

	@ConfigSection(
		name = "Low hides notification",
		description = "System notification when hides drop below 5",
		position = 4
	)
	String notifierSection = "notifier";

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show Overlay",
		description = "Show the cast count overlay when hides are in inventory",
		section = overlaySection
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showInefficientWarning",
		name = "Warn on inefficient tan",
		description = "Show a warning line when hide count is not a multiple of 5 — partial casts use the same runes for fewer hides",
		section = overlaySection
	)
	default boolean showInefficientWarning()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showCastTimer",
		name = "Show cast timer",
		description = "Show a countdown after each Tan Leather cast",
		section = castTimerSection
	)
	default boolean showCastTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "castTimerDimsScreen",
		name = "Dim screen during cast",
		description = "Dim the screen for the duration of the cast countdown",
		section = castTimerSection
	)
	default boolean castTimerDimsScreen()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSpellHighlight",
		name = "Highlight Tan Leather spell",
		description = "Outline Tan Leather on the Lunar spellbook when at least 5 tannable hides are in inventory",
		section = highlightSection
	)
	default boolean showSpellHighlight()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "spellHighlightColor",
		name = "Highlight colour",
		description = "Outline colour for the Tan Leather spell highlight",
		section = highlightSection
	)
	default Color spellHighlightColor()
	{
		return new Color(0, 255, 255, 200);
	}

	@ConfigItem(
		keyName = "lowHidesScreenDim",
		name = "Dim screen when out of hides",
		description = "Show a dark screen overlay with 'Out of hides!' when you run low. Move the mouse to dismiss.",
		section = dimSection
	)
	default boolean lowHidesScreenDim()
	{
		return true;
	}

	@ConfigItem(
		keyName = "lowHidesNotification",
		name = "Low hides notification",
		description = "Fire a notification when hides drop below 5 after casting. Toggle ON for a single sound during gameplay; click to customise tray, volume, or in-game message.",
		section = notifierSection
	)
	default Notification lowHidesNotification()
	{
		// Pre-configured defaults — when the user toggles this on, it just works:
		// single native sound, no tray (avoids double ding), no flash, fires during gameplay.
		return new Notification(
			false,                          // enabled (off by default)
			true,                           // initialized — use the values below, not RuneLite globals
			true,                           // override
			false,                          // tray (off so it doesn't double up with the sound)
			TrayIcon.MessageType.NONE,
			RequestFocusType.OFF,
			NotificationSound.NATIVE,       // single RuneLite ding
			"",                             // custom sound path (unused)
			100,                            // volume
			10000,                          // timeout ms
			false,                          // game chat message
			FlashNotification.DISABLED,     // no red flash
			new Color(0x46FF0000, true),    // flash colour (unused while flash disabled)
			true                            // sendWhenFocused — fire during gameplay
		);
	}
}

package com.tanleathertracker;

import com.google.inject.Provides;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.config.Notification;
import net.runelite.client.events.ConfigChanged;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.Set;

@PluginDescriptor(
	name = "Tan Leather Cast Tracker",
	description = "Cast counter and timer for the Tan Leather spell",
	tags = {"magic", "crafting", "lunar", "tan", "leather", "tracker", "cow", "snake", "dragon"}
)
public class TanLeatherTrackerPlugin extends Plugin implements MouseListener
{
	private static final Logger log = LoggerFactory.getLogger(TanLeatherTrackerPlugin.class);

	// Hides consumed by the Lunar Tan Leather spell
	static final Set<Integer> HIDE_ITEM_IDS = Set.of(
		1739, // Cowhide
		7801, // Snake hide
		1753, // Green dragon hide
		1751, // Blue dragon hide
		1749, // Red dragon hide
		1747  // Black dragon hide
	);

	// Cast cooldown — the actual re-cast window is shorter than the full 3-tick animation.
	// Empirically ~1.3s feels right; the animation finishes its tail visually after the
	// spell can already be re-queued.
	private static final long CAST_DURATION_MS = 1300L;

	// Tolerance between the Tan Leather animation firing and inventory updating
	private static final long ANIM_TO_INV_TOLERANCE_MS = 3500L;

	// The generic Lunar cast animation Tan Leather plays — paired with a hide-count drop
	// to disambiguate from other spells using the same animation
	private static final int TAN_LEATHER_CAST_ANIM = AnimationID.HUMAN_CASTLOWLVLALCHEMY;

	// Varbits.SPELLBOOK value for the Lunar spellbook
	private static final int LUNAR_SPELLBOOK_VARBIT_VALUE = 2;

	// How long the counter stays visible after the last cast even when inventory is empty
	private static final long COUNTER_LINGER_MS = 10_000L;

	// How long the "Out of runes" warning stays visible after a failed cast attempt
	private static final long OUT_OF_RUNES_DISPLAY_MS = 30_000L;

	@Inject
	private Client client;

	@Inject
	private TanLeatherTrackerConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Notifier notifier;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private TanLeatherTrackerOverlay overlay;

	@Inject
	private TanLeatherDimOverlay dimOverlay;

	@Inject
	private TanLeatherSpellHighlightOverlay spellHighlightOverlay;

	@Inject
	private OverlayManager overlayManager;

	private int castCount = 0;
	private int maxCasts = 0;
	private int prevHideCount = -1;
	private int currentHideCount = 0;
	private boolean hasRelevantItems = false;
	private boolean lowHides = false;
	private boolean sessionActive = false;
	private boolean notifiedLowHides = false;
	// True after a cast actually crosses the 5→<5 threshold. Reset on restock or mouse dismiss.
	// Starts false so flipping the config option doesn't immediately dim.
	private boolean dimArmed = false;
	private boolean mouseListenerRegistered = false;
	private long lastCastMillis = 0L;
	private long lastTanAnimMillis = 0L;
	private long lastOutOfRunesMillis = 0L;
	private boolean lastCastInefficient = false;

	public int getCastCount()
	{
		return castCount;
	}

	public int getMaxCasts()
	{
		return maxCasts;
	}

	public boolean hasRelevantItems()
	{
		return hasRelevantItems;
	}

	public boolean hasEnoughHidesForCast()
	{
		return currentHideCount >= 5;
	}

	public int getCurrentHideCount()
	{
		return currentHideCount;
	}

	public boolean isInefficient()
	{
		return hasRelevantItems && (currentHideCount % 5) != 0;
	}

	// Conventional max efficient load — 25 hides (5 full 5-hide casts).
	// Beyond this, the user has more than they can usefully cast in one inventory.
	private static final int MAX_EFFICIENT_HIDES = 25;

	public int hidesShortOfFullCast()
	{
		int rem = currentHideCount % 5;
		return rem == 0 ? 0 : 5 - rem;
	}

	public boolean shouldSuggestDeposit()
	{
		return currentHideCount > MAX_EFFICIENT_HIDES && (currentHideCount % 5) != 0;
	}

	public int hidesToDeposit()
	{
		return currentHideCount % 5;
	}

	public boolean isLastCastInefficient()
	{
		return lastCastInefficient;
	}

	public boolean shouldShowCounter()
	{
		if (hasRelevantItems)
		{
			return true;
		}
		return lastCastMillis > 0
			&& (System.currentTimeMillis() - lastCastMillis) < COUNTER_LINGER_MS;
	}

	public boolean isOutOfRunes()
	{
		return lastOutOfRunesMillis > 0
			&& (System.currentTimeMillis() - lastOutOfRunesMillis) < OUT_OF_RUNES_DISPLAY_MS;
	}

	public long getCastRemainingMs()
	{
		long elapsed = System.currentTimeMillis() - lastCastMillis;
		long remaining = CAST_DURATION_MS - elapsed;
		return remaining > 0 ? remaining : 0L;
	}

	public boolean isCastTimerActive()
	{
		return lastCastMillis > 0 && getCastRemainingMs() > 0;
	}

	public boolean shouldShowCastTimer()
	{
		return config.showCastTimer() && isCastTimerActive();
	}

	public boolean shouldShowCastDim()
	{
		return shouldShowCastTimer() && config.castTimerDimsScreen();
	}

	public boolean shouldShowDim()
	{
		return sessionActive
			&& lowHides
			&& dimArmed
			&& !isCastTimerActive()
			&& config.lowHidesScreenDim();
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(dimOverlay);
		overlayManager.add(spellHighlightOverlay);
		resetState();
		log.debug("Tan Leather Cast Tracker started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(dimOverlay);
		overlayManager.remove(spellHighlightOverlay);
		resetState();
		log.debug("Tan Leather Cast Tracker stopped");
	}

	private void resetState()
	{
		castCount = 0;
		maxCasts = 0;
		prevHideCount = -1;
		currentHideCount = 0;
		sessionActive = false;
		notifiedLowHides = false;
		lowHides = false;
		dimArmed = false;
		lastCastMillis = 0L;
		lastTanAnimMillis = 0L;
		lastOutOfRunesMillis = 0L;
		lastCastInefficient = false;
		if (mouseListenerRegistered)
		{
			mouseManager.unregisterMouseListener(this);
			mouseListenerRegistered = false;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"tanleathertracker".equals(event.getGroup())
			|| !"lowHidesNotification".equals(event.getKey()))
		{
			return;
		}
		// Force Customize/override on whenever the notification is enabled, so the user's
		// per-trigger settings always apply. Avoids confusion where toggling the notification
		// 'on' silently falls back to RuneLite global settings.
		Notification n = config.lowHidesNotification();
		if (n.isEnabled() && !n.isOverride())
		{
			Notification forced = new Notification(
				n.isEnabled(),
				true,                       // initialized
				true,                       // override
				n.isTray(),
				n.getTrayIconType(),
				n.getRequestFocus(),
				n.getSound(),
				n.getSoundName(),
				n.getVolume(),
				n.getTimeout(),
				n.isGameMessage(),
				n.getFlash(),
				n.getFlashColor(),
				n.isSendWhenFocused()
			);
			configManager.setConfiguration("tanleathertracker", "lowHidesNotification", forced);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM)
		{
			return;
		}
		String msg = event.getMessage();
		if (msg == null)
		{
			return;
		}
		// Matches both 'You do not have enough runes to cast this spell.'
		// and 'You do not have enough Nature Runes to cast this spell.' etc.
		String lower = msg.toLowerCase();
		if (lower.contains("do not have enough") && lower.contains("to cast this spell"))
		{
			lastOutOfRunesMillis = System.currentTimeMillis();
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Player local = client.getLocalPlayer();
		if (local == null || event.getActor() != local)
		{
			return;
		}
		int anim = local.getAnimation();
		if (anim != TAN_LEATHER_CAST_ANIM)
		{
			return;
		}
		// Animation 712 is shared with Low Alchemy on the Standard spellbook.
		// Require the player to be on the Lunar book before treating this as a Tan Leather cast.
		if (client.getVarbitValue(VarbitID.SPELLBOOK) != LUNAR_SPELLBOOK_VARBIT_VALUE)
		{
			return;
		}
		long now = System.currentTimeMillis();
		lastTanAnimMillis = now;
		// Only start the countdown if another cast can follow this one.
		// On the final cast (<=5 hides about to be consumed) the timer is just noise.
		if (currentHideCount > 5)
		{
			lastCastMillis = now;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		currentHideCount = countHides(event.getItemContainer());
		hasRelevantItems = currentHideCount > 0;

		long now = System.currentTimeMillis();
		boolean recentTanAnim = (now - lastTanAnimMillis) < ANIM_TO_INV_TOLERANCE_MS;
		boolean castDetected = prevHideCount != -1
			&& currentHideCount < prevHideCount
			&& recentTanAnim;
		boolean restocked = prevHideCount != -1 && currentHideCount > prevHideCount;

		// Mid-cycle restock — banking and withdrawing fresh hides resets the cycle
		if (restocked)
		{
			castCount = 0;
		}

		// Cast count logic — maxCasts counts only full 5-hide (efficient) casts
		if (castDetected)
		{
			if (castCount == 0)
			{
				// Lock in maxCasts from the hide count before this cast
				maxCasts = prevHideCount / 5;
			}
			castCount++;
			if (maxCasts > 0 && castCount >= maxCasts)
			{
				castCount = 0;
			}
			else if (maxCasts == 0)
			{
				// Inefficient cast on <5 hides — keep counter at 0
				castCount = 0;
			}
			sessionActive = true;
			lastCastInefficient = (prevHideCount - currentHideCount) < 5;
			// Successful cast clears any stale 'out of runes' warning
			lastOutOfRunesMillis = 0L;
			// Arm the dim only if this specific cast pushed us below 5
			if (prevHideCount >= 5 && currentHideCount < 5)
			{
				dimArmed = true;
			}
		}

		// Between cycles — sync maxCasts to current hide count
		if (castCount == 0)
		{
			maxCasts = currentHideCount / 5;
		}

		// Update low hides flag
		lowHides = currentHideCount < 5;

		// Fire the configurable notification once when hides drop below 5 after casting
		if (sessionActive && lowHides && !notifiedLowHides)
		{
			log.debug("Firing low-hides notification (currentHides={})", currentHideCount);
			notifier.notify(config.lowHidesNotification(), "Not enough hides for Tan Leather!");
			notifiedLowHides = true;
		}

		// Register mouse listener only when dim first becomes active
		boolean dimShouldShow = sessionActive
			&& lowHides
			&& dimArmed
			&& config.lowHidesScreenDim();

		if (dimShouldShow && !mouseListenerRegistered)
		{
			mouseManager.registerMouseListener(this);
			mouseListenerRegistered = true;
		}

		// Reset notifier + dim state when restocked to 5 or more
		if (currentHideCount >= 5)
		{
			notifiedLowHides = false;
			dimArmed = false;
		}

		prevHideCount = currentHideCount;
	}

	private int countHides(ItemContainer container)
	{
		int count = 0;
		Item[] items = container.getItems();
		if (items == null)
		{
			return 0;
		}
		for (Item item : items)
		{
			if (item != null && HIDE_ITEM_IDS.contains(item.getId()))
			{
				count += item.getQuantity();
			}
		}
		return count;
	}

	// --- MouseListener ---

	@Override
	public MouseEvent mouseMoved(MouseEvent event)
	{
		if (mouseListenerRegistered)
		{
			dimArmed = false;
			mouseManager.unregisterMouseListener(this);
			mouseListenerRegistered = false;
		}
		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event) { return event; }

	@Override
	public MouseEvent mousePressed(MouseEvent event) { return event; }

	@Override
	public MouseEvent mouseReleased(MouseEvent event) { return event; }

	@Override
	public MouseEvent mouseEntered(MouseEvent event) { return event; }

	@Override
	public MouseEvent mouseExited(MouseEvent event) { return event; }

	@Override
	public MouseEvent mouseDragged(MouseEvent event) { return event; }

